import{b as o,O as r,g as l,j as s}from"./chunks/framework.DSt9LnBW.js";const q=JSON.parse('{"title":"一个版本的一生：软件开发生命周期","description":"上一篇聊的是产品在市场上的那条线——导入、成长、成熟、衰退，以年计，问的是\\"这个产品还值不值得做\\"。","frontmatter":{"date":"2026-09-26T00:00:00.000Z","tags":["互联网","软件工程","流程","测试"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/internet-years/sdlc/index.md","filePath":"个人博客/在互联网的那些年/2.一个版本的一生.md","lastUpdated":1790295671000}'),n={name:"blog/internet-years/sdlc/index.md"};function a(i,t,e,p,g,u){return r(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="一个版本的一生-软件开发生命周期" tabindex="-1">一个版本的一生：软件开发生命周期 <a class="header-anchor" href="#一个版本的一生-软件开发生命周期" aria-label="Permalink to &quot;一个版本的一生：软件开发生命周期&quot;">​</a></h1><p>上一篇聊的是产品在市场上的那条线——导入、成长、成熟、衰退，以年计，问的是&quot;这个产品还值不值得做&quot;。</p><p>这篇换一条线，也叫生命周期，但尺度完全不同：<strong>一个版本从想法冒出来，到上线被人用起来</strong>。以周计，问的是&quot;这个版本能不能按时、保质地交付&quot;。</p><p>它有个正式名字：<strong>软件开发生命周期</strong>，缩写 <strong>SDLC</strong>（Software Development Life Cycle）。</p><p>名字听着像教科书目录，其实就是每天都在发生的事。用一个具体场景就能说清——</p><p>周一早上，产品经理在群里发了一句：</p><blockquote><p>订单列表加个导出按钮吧，客服天天手动复制，烦死了。</p></blockquote><p>这句话要怎么变成一个线上真能点的按钮？中间要走六步，每一步都在回答一个问题：</p><table tabindex="0"><thead><tr><th>步骤</th><th>回答的问题</th></tr></thead><tbody><tr><td>需求</td><td>到底要做什么？</td></tr><tr><td>设计</td><td>打算怎么做？</td></tr><tr><td>编码</td><td>做出来</td></tr><tr><td>测试</td><td>做对了吗？</td></tr><tr><td>上线</td><td>让用户用上</td></tr><tr><td>运维</td><td>用起来之后呢？</td></tr></tbody></table><p>六步走完，一个版本就算过完了一生。下面一步步拆。</p><h2 id="一、需求-到底要做什么" tabindex="-1">一、需求：到底要做什么 <a class="header-anchor" href="#一、需求-到底要做什么" aria-label="Permalink to &quot;一、需求：到底要做什么&quot;">​</a></h2><p>&quot;加个导出按钮&quot;听起来很清楚，实际上藏着十几个没说出口的问题：</p><ul><li>导出什么？当前这一页，还是筛选之后的全部？</li><li>什么格式？CSV、Excel，还是两个都要？</li><li>数据量多大？一千条和一百万条，做法完全不一样</li><li>谁能导？客服能导，普通用户也能吗？导出来的会不会是别人的订单？</li><li>字段里有敏感信息吗？手机号要不要打码？</li></ul><p>需求这一步，就是把这些坑一个个填掉，把一句口头愿望变成一条谁都挑不出歧义的话。比如最后落成：</p><blockquote><p>有导出权限的用户，在订单列表页可以把<strong>当前筛选条件下的订单</strong>导出为 <strong>CSV</strong>，单次上限<strong>一万条</strong>，超出需提示缩小范围。手机号字段脱敏。</p></blockquote><p><strong>产出</strong>：需求文档，或者至少一份大家点头认可的范围说明。</p><p><strong>最容易翻的车</strong>：需求方自己也没想清楚，把&quot;我觉得&quot;当成需求，开发边做边猜。等做完了才发现，做的是另一件事。</p><p>这里有个值得记住的规律：<strong>同一个问题，发现得越晚，修起来越贵。</strong> 在需求阶段改一句话，在编码阶段可能要改一天，上线之后才发现，可能得回滚、道歉、补数据。</p><p>那些&quot;1:10:100&quot;的说法（每往后一个阶段，修复成本涨一个数量级）不必当成精确公式，但它指的方向是对的——<strong>澄清是需求阶段最划算的投入</strong>。</p><h2 id="二、设计-打算怎么做" tabindex="-1">二、设计：打算怎么做 <a class="header-anchor" href="#二、设计-打算怎么做" aria-label="Permalink to &quot;二、设计：打算怎么做&quot;">​</a></h2><p>需求回答&quot;做什么&quot;，设计回答&quot;怎么做&quot;。</p><p>设计通常分两层，但经常被混在一起谈：</p><p><strong>产品设计</strong>：长什么样、点了之后发生什么。</p><p>导出按钮放哪、导出中要不要显示进度、失败了提示什么。别小看这些——如果一万条要等十秒，界面又没反应，用户会以为卡死了，然后连点三次，最后收到三个文件。</p><p><strong>技术设计</strong>：数据怎么查、接口怎么定、会不会把库拖垮。</p><ul><li>一百万条订单一次性查出来，数据库扛得住吗？</li><li>用户点一下要等 30 秒，浏览器会不会超时？要不要改成后台生成、生成好了再通知他？</li><li>CSV 手写就行，Excel 得引第三方库，值吗？</li><li>导出记录要不要留档——谁在什么时候导了多少条？万一出了数据泄漏，这是救命的证据。</li></ul><p><strong>产出</strong>：设计文档、接口文档、原型图。</p><p><strong>最容易翻的车</strong>：只设计了正常路径，没设计异常路径。</p><p>正常路径是&quot;用户点了导出，文件下来了&quot;。异常路径是&quot;导出到一半网络断了&quot;&quot;数据库超时了&quot;&quot;用户连点了三次&quot;。<strong>线上的问题，几乎都出在异常路径上。</strong></p><p>还有反方向的坑——<strong>过度设计</strong>。给一个导出功能上消息队列、分布式任务调度、独立导出服务。功能还没人用，先欠了一堆运维债。这类&quot;过早优化&quot;上一篇已经说过，代价是需求一旦被推翻，投入全部归零。</p><h2 id="三、编码-做出来" tabindex="-1">三、编码：做出来 <a class="header-anchor" href="#三、编码-做出来" aria-label="Permalink to &quot;三、编码：做出来&quot;">​</a></h2><p>把设计变成能跑的代码。这一步看起来最&quot;实&quot;，但有个容易被忽略的标准：<strong>&quot;写完&quot;不等于&quot;能交&quot;</strong>。</p><p>一个合格的&quot;编码完成&quot;，至少要包含四件事：</p><ol><li>功能跑得通</li><li>自己先点过一遍，关键逻辑有单元测试</li><li>代码过了评审，有人真的看过</li><li>提测时附一份说明：改了哪些文件、影响哪些模块、怎么验证</li></ol><p><strong>产出</strong>：可运行的代码 + 提测说明。</p><p><strong>最容易翻的车</strong>：</p><ul><li>写完直接甩给测试，一点没自测。测试一跑，全是&quot;按钮点不动&quot;这种低级问题，真正该测的逻辑反而没时间测了</li><li>不写提测说明。测试不知道改了什么，只能把整个模块重测一遍</li><li>大 PR：一次改三千行，评审变成走过场，真出了问题也定位不到是哪一行</li></ul><h2 id="四、测试-做对了吗" tabindex="-1">四、测试：做对了吗 <a class="header-anchor" href="#四、测试-做对了吗" aria-label="Permalink to &quot;四、测试：做对了吗&quot;">​</a></h2><p>测试这一步，很多人理解成&quot;找 bug&quot;。更准确的说法是：<strong>测试不生产 bug，测试生产&quot;质量信息&quot;。</strong></p><p>这个区别很重要。测试的最终产出不是一长串 bug 列表，而是一句话：</p><blockquote><p>这个版本可以上 / 有条件上 / 不能上，风险在 A、B、C 三处。</p></blockquote><p>因为要做的决策是&quot;上不上线&quot;，而不是&quot;有没有 bug&quot;——任何软件都有 bug，问题是有没有<strong>不能接受</strong>的 bug。</p><p>测试要回答三个问题：</p><ul><li><strong>需求说的功能，做对了吗？</strong>（功能测试）</li><li><strong>这次改动，有没有搞坏别的地方？</strong>（回归测试）</li><li><strong>性能、安全这些硬指标达标吗？</strong>（一般发布前做）</li></ul><p>回到导出功能，测的是这些：</p><ul><li>正常导出：列对不对、条数对不对、金额精度有没有丢</li><li>边界：0 条、1 条、刚好 1 万条、1 万零 1 条</li><li>权限：没有导出权限的用户，直接调接口能不能把数据拿出来——<strong>这是最容易漏、也最危险的一类问题</strong></li><li>异常：导出中途断开、连点三次、超大数据量时的表现</li></ul><p><strong>产出</strong>：测试报告，一份带结论的质量说明。</p><p><strong>最容易翻的车</strong>：</p><ul><li>提测质量太差，测试时间被前面几步吃掉，最后只能抽测</li><li>只测正常路径，边界和异常没覆盖</li><li>没有明确的上线标准，靠&quot;感觉差不多&quot;就放行</li></ul><p>完整的测试流程、用例怎么写、bug 怎么记录、什么标准才算能上线，站里有一整套，这里不重复：<a href="/testing/execution/test-process/">测试全流程</a>、<a href="/testing/appendix/test-case/">测试用例</a>、<a href="/testing/appendix/bug-record/">缺陷记录</a>、<a href="/testing/execution/regression-release/">回归测试与上线标准</a>。</p><h2 id="五、上线-让用户用上" tabindex="-1">五、上线：让用户用上 <a class="header-anchor" href="#五、上线-让用户用上" aria-label="Permalink to &quot;五、上线：让用户用上&quot;">​</a></h2><p>上线经常被误解成&quot;点一下发布按钮&quot;。它其实是一套有检查、有节奏、有退路的事：</p><ul><li><strong>上线前检查</strong>：配置对不对、数据库脚本备好没、依赖的服务都就绪了吗</li><li><strong>发布节奏</strong>：全量一次性上，还是先灰度 1%？（灰度就是先放给一小部分用户，看没问题再逐步扩大）</li><li><strong>上线后验证</strong>：在生产环境把核心链路真的走一遍，而不是&quot;应该没问题&quot;</li><li><strong>回滚预案</strong>：出问题几分钟能退回去？退回去数据会不会不一致？</li></ul><p><strong>产出</strong>：线上可用的版本。</p><p><strong>最容易翻的车</strong>：</p><ul><li><strong>没有回滚方案</strong>。上线出问题只能当场硬修，而现场改代码是最容易出二次事故的场景</li><li>上线后不验证，等用户找上门才知道坏了</li><li>周五下午上线。出了问题，整个周末都得处理——这条几乎是行业共识级的忌讳</li></ul><p>上线的完整清单（检查项、灰度策略、线上验证怎么做）见<a href="/testing/appendix/product-launch/">产品上线</a>。</p><h2 id="六、运维-用起来之后呢" tabindex="-1">六、运维：用起来之后呢 <a class="header-anchor" href="#六、运维-用起来之后呢" aria-label="Permalink to &quot;六、运维：用起来之后呢&quot;">​</a></h2><p>上线不是终点，而是第一个真正的起点。用户开始用了，你才会知道哪些设计是错的。</p><p>这一步包括三件事：</p><ul><li><strong>监控</strong>：出问题第一时间知道，而不是等用户打电话来才知道</li><li><strong>响应</strong>：线上问题怎么分级、谁来处理、多久响应</li><li><strong>迭代</strong>：把用户反馈和线上数据变成下一个版本的需求</li></ul><p>注意最后一条。迭代做的这件事，就是<strong>把第六步接回第一步</strong>。</p><p>所以 SDLC 不是一条从需求到上线的直线，<strong>它是一个圈</strong>——运维收集到的反馈，变成下一轮的需求，然后重新走一遍。</p><p><img src="https://op.yychuiyan.com/docs-blog/sdlc-loop.png" alt="软件开发生命周期的六步闭环：需求、设计、编码、测试、上线、运维依次推进，第六步运维收集到的反馈回到第一步需求，形成一轮轮循环"></p><p>这一点，正是它和上一篇那条产品生命周期的根本区别：<strong>产品周期是单向的、不可逆的；版本周期是循环的、可重复的。</strong> 产品走到衰退期就回不到成长期了，但版本可以一轮一轮地跑，每一轮都比上一轮好一点。</p><h2 id="六步是怎么串起来的-三种形态" tabindex="-1">六步是怎么串起来的：三种形态 <a class="header-anchor" href="#六步是怎么串起来的-三种形态" aria-label="Permalink to &quot;六步是怎么串起来的：三种形态&quot;">​</a></h2><p>上面说的是&quot;有哪些步骤&quot;。但真做起来，&quot;怎么把它们串起来&quot;有好几种打法，三种最常见：</p><table tabindex="0"><thead><tr><th>形态</th><th>怎么串</th><th>适合什么场景</th></tr></thead><tbody><tr><td><strong>瀑布</strong></td><td>一棒一棒传，上一棒做完才交下一棒</td><td>需求稳定、改动少</td></tr><tr><td><strong>敏捷</strong></td><td>切小，每一到四周跑完整一圈</td><td>需求会变、需要快速验证</td></tr><tr><td><strong>DevOps</strong></td><td>开发和运维不再分家，用自动化打通</td><td>追求又快又频繁地发布</td></tr></tbody></table><p>用个日常的类比：</p><ul><li>瀑布像<strong>接力赛</strong>——一棒交给下一棒。跑得可以很快，但<strong>交接的那一刻最容易掉棒</strong></li><li>敏捷像<strong>打乒乓球</strong>——一来一回，反馈特别快，错了马上能改</li><li>DevOps 像<strong>把接力赛改成一个人跑全程</strong>——中间的交接环节用自动化抹掉</li></ul><p>有件事得说清楚：<strong>这三种不是&quot;新老替换&quot;的关系。</strong></p><p>不是敏捷比瀑布先进、DevOps 又比敏捷先进。它们的差别只有一件事：<strong>你多久能拿到一次真实反馈。</strong></p><ul><li>需求一年前就冻结了、改个字段要赔钱（银行核心系统、硬件、合规项目）→ 瀑布那种确定性更值钱</li><li>需求随时会变、用户自己也说不清（大部分互联网产品）→ 敏捷的反馈速度更值钱</li></ul><p>选错了会怎样？在需求随时会变的场景下走瀑布，等于把&quot;走错了路&quot;的风险攒到最后一刻集中爆发。反过来，在需求稳定的场景下硬套敏捷，是把确定性白白扔掉。</p><h2 id="测试在里面到底占多大分量" tabindex="-1">测试在里面到底占多大分量 <a class="header-anchor" href="#测试在里面到底占多大分量" aria-label="Permalink to &quot;测试在里面到底占多大分量&quot;">​</a></h2><p>写到这里，前面那种&quot;六步&quot;的写法容易让人产生一个错觉：测试是第四步那个格子，前面三步做完了才轮到它。</p><p><strong>不是。</strong></p><p>测试是贯穿全程的。用一句流行的话说，叫&quot;测试左移&quot;——把质量活动往前挪：</p><table tabindex="0"><thead><tr><th>阶段</th><th>测试在这里做什么</th></tr></thead><tbody><tr><td>需求</td><td>需求说得清吗？验收标准定了吗？不定标准，后面拿什么判对错</td></tr><tr><td>设计</td><td>方案可测吗？日志、埋点、功能开关留了吗</td></tr><tr><td>编码</td><td>单元测试、自测、代码评审</td></tr><tr><td>测试</td><td>系统测试、回归测试</td></tr><tr><td>上线</td><td>线上验证、灰度观察</td></tr><tr><td>运维</td><td>线上监控、故障复盘</td></tr></tbody></table><p>为什么要左移？还是那条规律：<strong>发现得越晚，修起来越贵。</strong></p><p>再补一句，呼应上一篇：<strong>测试在 SDLC 里占多大分量，不是测试部门自己决定的，是产品所处的周期决定的。</strong></p><p>上一篇那张表里&quot;质量&quot;那一行——导入期轻验证、成长期上压测、成熟期算成本——说的就是这件事。同一个 SDLC，在产品导入期和成熟期，投入的方式和标准完全不同。<strong>流程的形状由阶段决定</strong>，这一点放在测试上尤其明显。</p><h2 id="一个常见的误解" tabindex="-1">一个常见的误解 <a class="header-anchor" href="#一个常见的误解" aria-label="Permalink to &quot;一个常见的误解&quot;">​</a></h2><p>&quot;我们小团队，哪搞这些流程，一个需求当天就上线了。&quot;</p><p>这话对了一半。</p><p>流程确实不是必须走的仪式，但<strong>那六步不是一个可选项清单，只是一件可以很快做完的事</strong>：</p><ul><li>&quot;需求&quot;可以是一条消息加一句回复确认——但不能没有</li><li>&quot;设计&quot;可以是白板上画两分钟——但不能没有</li><li>&quot;测试&quot;可以是自己拿真数据点一遍——但不能没有</li></ul><p>真正危险的不是&quot;把流程简化了&quot;，而是<strong>不知道这一步被跳过了</strong>。</p><p>比如上线前没想回滚方案。平时没事，出事那天就要通宵。省下的那十分钟，是用一整晚换的。</p><p>流程的价值不在于走完它，而在于<strong>你知道自己现在在哪一步、这一步的风险是什么、它出问题时代价有多大</strong>。知道之后选择跳过，那是判断；不知道就跳过，那是赌。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ol><li><strong>SDLC 就是六步，每一步回答一个问题</strong>：需求（做什么）→ 设计（怎么做）→ 编码（做出来）→ 测试（做对了吗）→ 上线（让用户用上）→ 运维（用起来之后呢）。</li><li><strong>它是个圈，不是一条线。</strong> 运维的反馈接回需求，一轮一轮跑。这也是它和产品生命周期最大的区别：产品周期单向不可逆，版本周期循环可重复。</li><li><strong>越往后越贵。</strong> 同一个问题，在需求阶段改一句话，上线后发现可能要回滚加道歉。所以&quot;澄清&quot;是需求阶段最划算的投入，&quot;左移&quot;是质量上最划算的动作。</li><li><strong>六步不是可选项，只是可以很快。</strong> 小团队可以十分钟走完，但不能不知道自己跳过了哪一步——知道之后跳过是判断，不知道就跳过是赌。</li><li><strong>瀑布、敏捷、DevOps 不是新老替换。</strong> 它们只差一件事：你多久能拿到一次真实反馈。选哪种打法，取决于需求有多不确定。</li></ol><p>上一篇讲了产品在市场上的一生，这篇讲了版本交付的一生。两者是嵌套的：<strong>外层那个周期，决定了内层这个圈该怎么跑、跑多快、标准多高。</strong></p>',93)])])}const h=o(n,[["render",a]]);export{q as __pageData,h as default};
